"""Original psychosis questions; classification systems are named where duration matters."""
from qbank_authoring import question,ref
rows=[]
PS=ref('NICE psychosis and schizophrenia management','https://www.nice.org.uk/guidance/cg178/chapter/recommendations')
AN=ref('Australian/New Zealand GRADE schizophrenia guideline: diagnostic criteria and management','https://pmc.ncbi.nlm.nih.gov/articles/PMC13000005/')
CT=ref('British Association for Psychopharmacology catatonia consensus guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC10101189/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('Which finding is a positive symptom of schizophrenia?', 'A fixed persecutory delusion',[
 ('Avolition','Reduced initiation is a negative-symptom domain.'),('Blunted affect','Reduced emotional expression is a negative symptom.'),('Alogia','Reduced speech output is a negative symptom.')],
 'Positive describes added abnormal experience rather than a favorable symptom','**Delusions and hallucinations are central positive symptoms.**',['Disorganized speech/behavior are additional important dimensions.','Negative and cognitive symptoms often contribute substantially to disability.'],'**Assess all domains and their functional consequences.**',['Do not use positive-symptom improvement as the only recovery measure.','Review mood, cognition, self-care and social participation.'],[['Positive','Delusions/hallucinations'],['Negative','Reduced motivation/expression'],['Cognitive','Attention/executive difficulties']],[PS,AN])

q('A patient with schizophrenia appears withdrawn and inactive after a dose increase, with rigidity and daytime somnolence. What is the best interpretation?', 'Secondary contributors such as sedation and parkinsonism should be assessed before labeling all inactivity as primary negative symptoms',[
 ('The dose response proves irreversible primary avolition','Treatment adverse effects are a plausible modifiable contributor.'),('All negative symptoms are necessarily medication-induced','Primary negative symptoms also occur.'),('Withdrawal alone establishes a new major depressive episode','A depressive syndrome requires additional assessment.')],
 'Reduced activity is a phenotype with several causes','**Depression, extrapyramidal effects, sedation and persistent psychosis can mimic or worsen negative symptoms.**',['Assess the time course relative to treatment.','Separate subjective distress and motivation from motor slowing.'],'**Address modifiable causes and reassess function.**',['Review medication burden and dose collaboratively.','Provide rehabilitation even when symptoms are partly primary.'],[['Primary','Illness-related negative symptoms'],['Secondary','Mood/drugs/positive symptoms'],['Assessment','Temporal and functional review']],[PS,AN],style='clinical_scenario')

q('A patient says that strangers can hear thoughts directly as they occur, without speaking or any device. Which phenomenon is described?', 'Thought broadcasting',[
 ('Thought insertion','This is the belief that thoughts are being placed into the mind by an external source.'),('Thought withdrawal','This is the belief that thoughts are being removed.'),('An obsession with preserved recognition of its irrational nature','The described fixed belief concerns external access to thoughts rather than an intrusive resisted thought.')],
 'Describe the experience before assigning a disease label','**Thought broadcasting is a belief that one’s thoughts are accessible to others.**',['The phenomenon can occur in psychotic disorders but is not a standalone diagnosis.','Clarify cultural and metaphorical meanings before interpreting it.'],'**Assess conviction, context, distress and associated symptoms.**',['Evaluate mood, substances and medical causes.','Use nonconfrontational questioning to understand the experience.'],[['Broadcasting','Others know thoughts directly'],['Insertion','Thoughts placed externally'],['Withdrawal','Thoughts removed externally']],[AN])

q('A patient hears two voices discussing the patient while alone, with no external speaker present. Which term best describes the perceptual phenomenon?', 'Auditory hallucination',[
 ('Auditory illusion','An illusion is a misinterpretation of a real external stimulus.'),('Delusion of reference','This concerns the meaning assigned to events, not the perception itself.'),('Thought blocking','This is an interruption in the train of thought.')],
 'Separate perception from belief','**A hallucination is a perception-like experience without the corresponding external stimulus.**',['Assess modality, timing, content and degree of insight.','Hearing voices is not specific to schizophrenia.'],'**Ask about distress, commands and ability to resist dangerous instructions.**',['Review sleep, trauma, substances and neurological conditions.','Assess the complete syndrome rather than one symptom.'],[['Hallucination','No matching external stimulus'],['Illusion','Misinterpreted real stimulus'],['Delusion','Belief-level disturbance']],[PS,AN],style='clinical_scenario')

q('During an interview, a patient shifts between loosely connected ideas so that the overall meaning becomes difficult to follow. Which finding is being assessed?', 'Formal thought disorder expressed through disorganized speech',[
 ('A fixed delusion as the only explanation','Delusion concerns thought content rather than the organization of speech.'),('Alogia','Alogia is reduced quantity or content of speech, not this disorganization.'),('Thought broadcasting','That concerns a belief about external access to thoughts.')],
 'Speech reveals the organization as well as the content of thought','**Disorganized connections can impair comprehensibility.**',['Distinguish tangentiality, derailment and incoherence descriptively.','Language, education and cultural context affect interpretation.'],'**Assess associated mood, psychosis, cognition and medical state.**',['Mania and delirium can also disrupt speech organization.','Do not diagnose schizophrenia from one conversational oddity.'],[['Form','Organization'],['Content','Beliefs/themes'],['Output','Quantity and fluency']],[AN],style='clinical_scenario')

q('Using DSM-5-TR duration conventions, a patient has continuous disturbance for 8 months including 2 months of active delusions, hallucinations and disorganized speech, with functional decline and no mood, substance or medical explanation. Which diagnosis best fits?', 'Schizophrenia',[
 ('Schizophreniform disorder','The total duration exceeds the one-to-six-month range.'),('Brief psychotic disorder','The course exceeds one month.'),('Delusional disorder','Prominent hallucinations/disorganization and broader decline do not fit that narrower syndrome.')],
 'Name the diagnostic framework when using duration thresholds','**DSM schizophrenia requires a sufficiently prolonged disturbance with the appropriate active symptoms.**',['ICD and DSM duration conventions are not identical.','Function, exclusions and the longitudinal mood relationship remain essential.'],'**Use duration as one part of a full formulation.**',['Review collateral history and treatment effects on the observed course.','Provide early intervention without waiting for every long-term label to be settled.'],[['DSM schizophrenia','At least 6 months total disturbance'],['Schizophreniform','1 to less than 6 months'],['Brief psychotic','Less than 1 month']],[AN],style='clinical_scenario')

q('Under DSM-5-TR conventions, a first psychotic syndrome meeting the symptom criteria has lasted 2 months and secondary causes are excluded. Which provisional duration-based diagnosis is most appropriate?', 'Schizophreniform disorder',[
 ('Schizophrenia already established solely from this duration','The DSM total-duration requirement has not yet been met.'),('Brief psychotic disorder','The syndrome has exceeded one month.'),('Cyclothymic disorder','This is a mood-course diagnosis rather than the described psychotic syndrome.')],
 'Early labels can change with longitudinal observation','**The one-to-six-month range fits schizophreniform disorder in the stated framework.**',['Outcome and course cannot be assumed from the first episode.','Assessment of affective and secondary causes continues.'],'**Treat and support promptly rather than delaying for diagnostic certainty.**',['Use early-intervention services where available.','Monitor function, symptoms and adverse effects.'],[['Duration','2 months'],['Framework','DSM-5-TR'],['Working diagnosis','Schizophreniform']],[AN],style='clinical_scenario')

q('A patient has an acute psychotic episode lasting 12 days followed by complete return to baseline, with no secondary or mood cause. Under DSM-5-TR conventions, which diagnosis is most consistent?', 'Brief psychotic disorder',[
 ('Schizophrenia','The prolonged total-duration criterion is not met.'),('Schizophreniform disorder','The episode is shorter than one month.'),('Persistent delusional disorder as established by any delusion','The overall acute episode and short duration favor another category.')],
 'Short duration and recovery define a distinct course','**Brief psychotic disorder has a limited episode duration with eventual return to baseline.**',['A precipitating stressor may be present but is not required in every case.','Continue assessing medical, substance and affective explanations.'],'**Arrange follow-up despite apparent complete recovery.**',['Review recurrence risk and early warning signs.','Support function and evaluate the precipitating context.'],[['Duration','More than 1 day and less than 1 month'],['Recovery','Return to baseline'],['Follow-up','Still necessary']],[AN],style='clinical_scenario')

q('Under DSM-5-TR conventions, which longitudinal finding helps distinguish schizoaffective disorder from psychosis occurring only in a mood disorder?', 'At least 2 weeks of delusions or hallucinations without a major mood episode, with major mood episodes present for most of the total illness duration',[
 ('Any hallucination during a severe depressive episode','Psychosis can occur within depression without schizoaffective disorder.'),('A single day of anxiety during chronic schizophrenia','Anxiety is not a qualifying major mood episode.'),('Psychosis exclusively during manic episodes','This supports bipolar disorder with psychotic features rather than the required independent psychotic interval.')],
 'The timeline is more informative than a cross-sectional symptom list','**Schizoaffective diagnosis requires a particular relationship between psychosis and major mood episodes.**',['The independent psychotic interval alone is not the whole criterion set.','The proportion of the overall course occupied by mood episodes matters.'],'**Construct a longitudinal episode timeline with collateral evidence.**',['Distinguish schizoaffective disorder from schizophrenia with brief mood symptoms.','Avoid applying DSM duration rules to a different classification system without qualification.'],[['Mood psychosis','Psychosis confined to mood episodes'],['Schizoaffective DSM','Independent psychosis plus predominant mood-episode burden'],['Schizophrenia','Mood episodes absent or a minority of course']],[AN])

q('An adult has a persistent nonbizarre jealous delusion but otherwise organized speech and relatively preserved function outside its consequences, without prominent hallucinations or a full mood syndrome. Which diagnosis is most consistent?', 'Delusional disorder',[
 ('Schizophrenia as established by any fixed false belief','The broader characteristic symptom/function pattern is not described.'),('Obsessive-compulsive disorder with good insight','A fixed conviction is different from an intrusive thought recognized as unreasonable.'),('Delirium','There is no acute fluctuating attention or awareness disturbance.')],
 'A delusion does not automatically define schizophrenia','**Delusional disorder has a more circumscribed psychotic presentation.**',['Exclude mood, substances and medical causes.','Risk can be significant despite relatively preserved general functioning.'],'**Assess consequences, safety and treatment engagement.**',['Explore the belief respectfully without endorsing it.','Consider collateral information and effects on relationships.'],[['Core','Persistent delusion'],['Organization','Relatively preserved outside consequences'],['Exclusions','Mood/substance/medical causes']],[AN],style='clinical_scenario')

q('A young adult with new psychosis develops seizures, dyskinesias, autonomic instability and reduced consciousness. Which next step is most appropriate?', 'Urgently investigate a neurological or medical cause, including autoimmune encephalitis when appropriate',[
 ('Assume uncomplicated schizophrenia and defer medical workup','The neurological and autonomic red flags require urgent assessment.'),('Diagnose a primary anxiety disorder from tachycardia alone','This does not explain seizures and encephalopathy.'),('Treat the movement disorder as definitive proof of chronic tardive dyskinesia','The new illness and systemic findings indicate a different differential.')],
 'Psychosis can be one component of encephalitis','**Seizures, altered consciousness and autonomic/movement abnormalities are major red flags.**',['Assess infectious, autoimmune, toxic and metabolic causes.','A psychiatric presentation does not exclude brain disease.'],'**Coordinate neurological, medical and psychiatric care promptly.**',['Use MRI, EEG, CSF and antibody testing according to the clinical syndrome.','Support breathing, circulation and seizure control while investigating.'],[['Psychosis alone','Broad differential'],['Neurological red flags','Medical escalation'],['Evaluation','Syndrome-directed testing']],[PS,ref('Autoimmune encephalitis clinical diagnostic approach','https://pmc.ncbi.nlm.nih.gov/articles/PMC5066574/')],style='clinical_scenario')

q('A patient is mute, holds imposed postures, resists instructions and shows waxy flexibility. Which syndrome should be assessed?', 'Catatonia',[
 ('Alogia alone','Reduced speech does not explain the distinctive psychomotor signs.'),('Parkinsonism alone','Rigidity and slowing can overlap, but posturing and waxy flexibility suggest catatonia.'),('Uncomplicated depression without a psychomotor syndrome','Catatonia can accompany mood disorders and requires specific assessment.')],
 'Catatonia is a syndrome across psychiatric and medical causes','**Motor, behavioral and speech abnormalities cluster in a recognizable pattern.**',['It is not confined to schizophrenia.','Immobility can cause dehydration, pressure injury, thrombosis and other complications.'],'**Assess cause and provide specific treatment and supportive prevention.**',['A monitored lorazepam challenge can support diagnosis.','Severe or refractory disease may require ECT.'],[['Signs','Mutism/posturing/waxy flexibility'],['Causes','Mood, psychotic and medical disorders'],['Treatment','Benzodiazepine/ECT pathways']],[CT],style='clinical_scenario')
